.input {$value :number minimumFractionDigits=1 signDisplay=always}
.local $copy = {$value :number}
.local $decimal = {1 :number minimumFractionDigits=2 minimumSignificantDigits=3}
.local $integer = {$decimal :integer}
.local $integerCopy = {$integer :number}
.local $percent = {1 :percent minimumFractionDigits=2}
.local $percentCopy = {$percent :number}
.match $copy
one {{one {$copy}; integer {$integerCopy}; percent {$percentCopy}}}
other {{other {$copy}; integer {$integerCopy}; percent {$percentCopy}}}
* {{fallback {$copy}; integer {$integerCopy}; percent {$percentCopy}}}
